public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    List<Integer> current = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to limit candidate substrings
    String shortest = strings.get(0);
    for (String s : strings) {
        if (s.length() < shortest.length()) {
            shortest = s;
        }
    }

    int shortestLen = shortest.length();

    // Check lengths from longest to shortest
    for (int len = shortestLen; len >= 1; len--) {
        // Generate all substrings of this length from the shortest string
        for (int start = 0; start + len <= shortestLen; start++) {
            String candidate = shortest.substring(start, start + len);
            String revCandidate = new StringBuilder(candidate).reverse().toString();

            boolean allMatch = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(revCandidate))) {
                    allMatch = false;
                    break;
                }
            }

            if (allMatch) {
                return len;
            }
        }
    }

    return 0;
}

