public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // If start and end are the same, travel is trivially possible
    if (start.length != end.length) {
        return "cannot be travelled";
    }
    boolean same = true;
    for (int i = 0; i < start.length; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map using string keys for coordinates
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 4) {
            continue; // skip invalid path entries
        }
        String a = path[0] + "," + path[1];
        String b = path[2] + "," + path[3];
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    // BFS to check connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

