private int dfs(String s, int index, java.util.Set<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = 1 + dfs(s, end, used);
            if (res > max) {
                max = res;
            }
            used.remove(sub);
        }
    }
    return max;
}

