public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int maxSum = max * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) isSquare[i * i] = true;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < memo.length; i++) {
        for (int j = 0; j < memo[i].length; j++) {
            memo[i][j] = -1;
        }
    }
    int allMask = (1 << n) - 1;
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dfs(i, 1 << i, A, isSquare, memo, allMask);
    }
    return result;
}

private static int dfs(int last, int mask, int[] A, boolean[] isSquare, int[][] memo, int allMask) {
    if (mask == allMask) return 1;
    if (memo[mask][last] != -1) return memo[mask][last];
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if ((mask & (1 << i)) == 0 && isSquare[A[last] + A[i]]) {
            count += dfs(i, mask | (1 << i), A, isSquare, memo, allMask);
        }
    }
    memo[mask][last] = count;
    return count;
}

public static int largestRectangleArea(int[] heights) {
