    int[] result = new int[m * n];
    int idx = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        int start = Math.max(0, k - n + 1);
        int end = Math.min(k, m - 1);
        if (k % 2 == 0) {
            for (int i = end; i >= start; i--) {
                result[idx++] = mat[i][k - i];
            }
        } else {
            for (int i = start; i <= end; i++) {
                result[idx++] = mat[i][k - i];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 1;
    while (i > 0 && digits[i - 1] >= digits[i]) {
        i--;
    }
    if (i <= 0) {
        return -1;
    }
    int pivot = i - 1;
    int j = digits.length - 1;
    while (digits[j] <= digits[pivot]) {
        j--;
    }
    char temp = digits[pivot];
    digits[pivot] = digits[j];
    digits[j] = temp;
    int left = i, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

